import { Suspense, lazy, useEffect, useMemo, useState } from "react";
import { FluentProvider } from "@fluentui/react-components";
import { ja } from "./strings/ja";
import { hsLightTheme, hsDarkTheme } from "./theme/fluentTheme";
import { useThemeMode } from "./theme/useThemeMode";
import { AppShell } from "./components/AppShell";
import { TitleBar } from "./components/TitleBar";
import { CommandBar } from "./components/CommandBar";
import { WaveformView } from "./components/WaveformView";
import { ScoreWorkspace } from "./components/ScoreWorkspace";
import { PropertiesPanel } from "./components/PropertiesPanel";
import { TransportBar } from "./components/TransportBar";
import { StatusBar } from "./components/StatusBar";
import { SettingsView } from "./components/SettingsView";
import type { PitchView } from "./components/PitchSegmented";
import {
  createCommands,
  dispatchCommand,
  type CommandContext,
} from "./commands/registry";
import { getShellInfo } from "./tauri/bridge";

type View = "workspace" | "settings";

/** "#/dev/gallery" — dev-only internal component gallery (UI-010). */
const GALLERY_HASH = "#/dev/gallery";
// Lazy so the gallery (and its Fluent imports) stay out of the prod bundle.
const DevGallery = import.meta.env.DEV
  ? lazy(() => import("./dev/Gallery"))
  : null;

/**
 * UI-001 spike shell. Screen state is fixed to EMPTY (GUI_UX_SPEC §27):
 * no audio, no score, no engine. The shell proves layout, theming,
 * Japanese copy, keyboard focus, IPC plumbing and the CSP/capability
 * baseline before real features are wired in.
 */
export default function App() {
  const { mode, resolved, select } = useThemeMode();
  const [view, setView] = useState<View>("workspace");
  const [pitch, setPitch] = useState<PitchView>("concert");
  const [statusMessage, setStatusMessage] = useState<string>(ja.status.ready);
  const [shellDetail, setShellDetail] = useState<string | undefined>(
    ja.status.shellInfoLoading,
  );
  const [hash, setHash] = useState(() => window.location.hash);

  // EMPTY state: nothing loaded yet.
  const shellState = useMemo(
    () => ({ hasAudio: false, hasScore: false, reviewCount: 0 }),
    [],
  );
  const commands = useMemo(() => createCommands(shellState), [shellState]);

  const ctx = useMemo<CommandContext>(
    () => ({
      setPitchView: setPitch,
      openAudioRequested: () => setStatusMessage(ja.status.spikeNoFileOpen),
      openSettings: () => setView("settings"),
    }),
    [],
  );

  // Hash routing is only used for the internal dev gallery; the product
  // shell is a single workspace (GUI_UX_SPEC §2), not a page router.
  useEffect(() => {
    const onHashChange = () => setHash(window.location.hash);
    window.addEventListener("hashchange", onHashChange);
    return () => window.removeEventListener("hashchange", onHashChange);
  }, []);

  // Central shortcut dispatch (GUI_UX_SPEC §23).
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if (dispatchCommand(e, commands, ctx)) e.preventDefault();
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [commands, ctx]);

  // Prove the JS↔Rust IPC channel early; populates the status area.
  useEffect(() => {
    let alive = true;
    getShellInfo().then((info) => {
      if (!alive) return;
      setShellDetail(
        info ? `v${info.version}` : undefined, // browser dev: no shell info
      );
      setStatusMessage(ja.status.ready);
    });
    return () => {
      alive = false;
    };
  }, []);

  const theme = resolved === "dark" ? hsDarkTheme : hsLightTheme;
  // Dev-only route: the gallery renders in place of the shell and never
  // appears in product navigation.
  const showGallery = DevGallery != null && hash === GALLERY_HASH;

  return (
    <FluentProvider theme={theme}>
      {showGallery ? (
        <Suspense fallback={null}>
          <DevGallery themeMode={mode} onThemeMode={select} />
        </Suspense>
      ) : (
        <AppShell>
          <TitleBar />
          {view === "settings" ? (
            <div className="hs-settings-wrap">
              <SettingsView
                themeMode={mode}
                onThemeMode={select}
                onBack={() => setView("workspace")}
              />
            </div>
          ) : (
            <>
              <CommandBar
                commands={commands}
                ctx={ctx}
                pitch={pitch}
                onPitch={setPitch}
              />
              <WaveformView />
              <div className="hs-main">
                <ScoreWorkspace onOpenAudio={ctx.openAudioRequested} />
                <PropertiesPanel />
              </div>
              <TransportBar enabled={shellState.hasAudio} />
            </>
          )}
          <StatusBar message={statusMessage} detail={shellDetail} />
        </AppShell>
      )}
    </FluentProvider>
  );
}

import { ja } from "../strings/ja";
import {
  SegmentedControl,
  type SegmentedOption,
} from "./primitives/SegmentedControl";

export type PitchView = "concert" | "hornF";

const OPTIONS: readonly SegmentedOption<PitchView>[] = [
  { value: "concert", label: ja.pitch.concert },
  { value: "hornF", label: ja.pitch.hornF },
];

/**
 * コンサートピッチ / F管ホルン selector (DESIGN_SYSTEM §11) — thin binding of
 * the SegmentedControl primitive to the pitch-view domain. Keyboard:
 * ArrowLeft/Right inside the group; Ctrl+1 / Ctrl+2 globally via the command
 * registry (GUI_UX_SPEC §7).
 */
export function PitchSegmented({
  value,
  onChange,
}: {
  value: PitchView;
  onChange: (v: PitchView) => void;
}) {
  return (
    <SegmentedControl
      options={OPTIONS}
      value={value}
      onChange={onChange}
      ariaLabel={ja.pitch.regionLabel}
    />
  );
}

import { FolderOpen24Regular } from "@fluentui/react-icons";
import { ja } from "../strings/ja";
import { HsButton } from "./primitives/Button";

/**
 * Score workspace — EMPTY state (GUI_UX_SPEC §3, §27).
 * No transcription settings, backend names, FFmpeg/quantizer details, or
 * score tools are surfaced here; just the drop target copy + one CTA.
 */
export function ScoreWorkspace({
  onOpenAudio,
}: {
  onOpenAudio(): void;
}) {
  return (
    <main
      className="hs-score"
      role="region"
      aria-label={ja.score.regionLabel}
      tabIndex={0}
    >
      <div className="hs-empty">
        <p className="hs-empty__title">{ja.emptyState.title}</p>
        <p className="hs-empty__or">{ja.emptyState.or}</p>
        <HsButton
          variant="primary"
          size="large"
          icon={<FolderOpen24Regular />}
          onClick={onOpenAudio}
        >
          {ja.emptyState.open}
        </HsButton>
        <p className="hs-empty__formats">{ja.emptyState.formats}</p>
        <p className="hs-empty__privacy">{ja.emptyState.privacy}</p>
      </div>
    </main>
  );
}

import { Radio, RadioGroup, Label } from "@fluentui/react-components";
import { ArrowLeft24Regular } from "@fluentui/react-icons";
import { ja } from "../strings/ja";
import type { ThemeMode } from "../theme/fluentTheme";
import { HsButton } from "./primitives/Button";
import { HsPanel } from "./primitives/Panel";

/**
 * 設定 — auxiliary screen, not a work mode (GUI_UX_SPEC §18).
 * Only 外観→テーマ is functional in this spike; remaining sections render as
 * placeholders so the page structure and Japanese density are testable.
 */
export function SettingsView({
  themeMode,
  onThemeMode,
  onBack,
}: {
  themeMode: ThemeMode;
  onThemeMode(m: ThemeMode): void;
  onBack(): void;
}) {
  return (
    <div className="hs-settings" role="region" aria-label={ja.settings.regionLabel}>
      <HsButton
        variant="subtle"
        icon={<ArrowLeft24Regular />}
        onClick={onBack}
      >
        {ja.settings.back}
      </HsButton>
      <h1 className="hs-settings__title">{ja.settings.title}</h1>

      <HsPanel
        title={ja.settings.appearanceSection}
        titleLevel={2}
        className="hs-settings__section"
      >
        <Label id="hs-theme-label">{ja.settings.themeLabel}</Label>
        <RadioGroup
          aria-labelledby="hs-theme-label"
          value={themeMode}
          onChange={(_, data) => onThemeMode(data.value as ThemeMode)}
        >
          <Radio value="system" label={ja.settings.themeSystem} />
          <Radio value="light" label={ja.settings.themeLight} />
          <Radio value="dark" label={ja.settings.themeDark} />
        </RadioGroup>
      </HsPanel>

      {(
        [
          ja.settings.playbackSection,
          ja.settings.transcriptionSection,
          ja.settings.exportSection,
          ja.settings.toolsSection,
          ja.settings.advancedSection,
        ] as const
      ).map((title) => (
        <HsPanel
          key={title}
          title={title}
          titleLevel={2}
          className="hs-settings__section"
        >
          <p className="hs-settings__note">{ja.settings.placeholder}</p>
        </HsPanel>
      ))}
    </div>
  );
}

import { forwardRef, type ReactElement, type ReactNode } from "react";
import {
  Button as FluentButton,
  Spinner,
  mergeClasses,
} from "@fluentui/react-components";

/**
 * HsButton — HornScribe button primitive over Fluent v9 Button
 * (DESIGN_SYSTEM §9).
 *
 * Variants:
 * - `primary`   — the single primary action of a surface (§9: 原則1つ)
 * - `secondary` — default neutral command
 * - `subtle`    — borderless, low-emphasis command
 * - `danger`    — destructive actions only (§20); fill uses the palette-red
 *                 --hs-danger* semantic tokens, never the status-error
 *                 signal color on its own
 *
 * `loading` shows an inline spinner, disables interaction and marks the
 * control aria-busy while keeping the Japanese label visible.
 *
 * forwardRef so Fluent Tooltip / Menu / Popover / Dialog triggers can
 * anchor to the underlying <button>.
 */
export type HsButtonVariant = "primary" | "secondary" | "subtle" | "danger";

const APPEARANCE: Record<
  HsButtonVariant,
  "primary" | "secondary" | "subtle"
> = {
  primary: "primary",
  secondary: "secondary",
  subtle: "subtle",
  // danger renders on the primary fill slot; the --hs-danger* tokens in
  // styles.css re-tint it to the destructive red family.
  danger: "primary",
};

export interface HsButtonProps {
  variant?: HsButtonVariant;
  icon?: ReactElement;
  /** Spinner + disabled + aria-busy while keeping the label. */
  loading?: boolean;
  disabled?: boolean;
  size?: "small" | "medium" | "large";
  type?: "button" | "submit";
  onClick?: () => void;
  /** Extra accessible name when the visible label needs context. */
  ariaLabel?: string;
  className?: string;
  children: ReactNode;
}

export const HsButton = forwardRef<HTMLButtonElement, HsButtonProps>(
  function HsButton(
    {
      variant = "secondary",
      icon,
      loading = false,
      disabled = false,
      size = "medium",
      type = "button",
      onClick,
      ariaLabel,
      className,
      children,
    },
    ref,
  ) {
    return (
      <FluentButton
        ref={ref}
        appearance={APPEARANCE[variant]}
        className={mergeClasses(
          "hs-button",
          `hs-button--${variant}`,
          className,
        )}
        icon={loading ? <Spinner size="tiny" /> : icon}
        disabled={disabled || loading}
        aria-busy={loading || undefined}
        aria-label={ariaLabel}
        size={size}
        type={type}
        onClick={onClick}
      >
        {children}
      </FluentButton>
    );
  },
);

import type { ReactElement, ReactNode } from "react";
import {
  Dialog as FluentDialog,
  DialogTrigger as FluentDialogTrigger,
  DialogSurface as FluentDialogSurface,
  DialogBody as FluentDialogBody,
  DialogTitle as FluentDialogTitle,
  DialogContent as FluentDialogContent,
  DialogActions as FluentDialogActions,
  makeStyles,
  tokens,
} from "@fluentui/react-components";

/**
 * HsDialog — modal surface (§7 modal radius, §8 elevation, §20 error shape).
 *
 * Body copy follows the copy contract: title = what failed / what's asked,
 * content = impact, actions = recovery. Danger variants belong on the
 * caller's action buttons (HsButton variant="danger"), not on the dialog.
 *
 * `modalType` is Fluent's: "modal" (default, backdrop + focus trap),
 * "non-modal", or "alert" (no light-dismiss — reserve for destructive
 * confirmations per JAPANESE_UI_COPY §8).
 */
const useDialogStyles = makeStyles({
  surface: {
    borderRadius: "var(--hs-radius-modal)",
    boxShadow: tokens.shadow64,
    // §18 dialog motion tier; collapses to ~0 under reduced-motion tokens.
    transitionDuration: "var(--hs-motion-dialog)",
    transitionTimingFunction: "var(--hs-ease-decelerate)",
  },
});

export interface HsDialogProps {
  open: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Japanese title — required, dialogs always carry a heading. */
  title: string;
  /** Body content (DialogContent). */
  children: ReactNode;
  /** Footer actions (DialogActions), e.g. キャンセル + primary action. */
  actions?: ReactNode;
  /** Optional trigger element wrapped in DialogTrigger. */
  trigger?: ReactElement;
  /** Mount the surface into this node instead of document.body. */
  mountNode?: HTMLElement | null;
  modalType?: "modal" | "non-modal" | "alert";
}

export function HsDialog({
  open,
  onOpenChange,
  title,
  children,
  actions,
  trigger,
  mountNode,
  modalType = "modal",
}: HsDialogProps) {
  const styles = useDialogStyles();
  return (
    <FluentDialog
      open={open}
      onOpenChange={(_, data) => onOpenChange?.(data.open)}
      modalType={modalType}
    >
      {trigger ? (
        <FluentDialogTrigger disableButtonEnhancement>
          {trigger}
        </FluentDialogTrigger>
      ) : (
        <></>
      )}
      <FluentDialogSurface className={styles.surface} mountNode={mountNode}>
        <FluentDialogBody>
          <FluentDialogTitle>{title}</FluentDialogTitle>
          <FluentDialogContent>{children}</FluentDialogContent>
          {actions ? (
            <FluentDialogActions>{actions}</FluentDialogActions>
          ) : null}
        </FluentDialogBody>
      </FluentDialogSurface>
    </FluentDialog>
  );
}

import { forwardRef, type ReactElement } from "react";
import {
  Button as FluentButton,
  Spinner,
  mergeClasses,
} from "@fluentui/react-components";
import { HsTooltip } from "./Tooltip";

/**
 * HsIconButton — icon-only command (DESIGN_SYSTEM §9, §24).
 *
 * The copy contract (docs/UI_COPY_CONTRACT.md §4) requires icon-only
 * buttons to carry BOTH a Japanese tooltip and an accessible name, so
 * `label` is a required prop: it feeds the Tooltip content AND aria-label.
 *
 * `selected` marks toggle-style buttons: it sets aria-pressed and switches
 * the appearance so the state reads through more than color alone.
 *
 * forwardRef so Fluent triggers/tooltips can anchor to the <button>.
 */
export interface HsIconButtonProps {
  /** Japanese label — used for the tooltip AND the accessible name. */
  label: string;
  icon: ReactElement;
  variant?: "subtle" | "secondary" | "primary";
  /** Toggle semantics: aria-pressed + filled appearance cue. */
  selected?: boolean;
  loading?: boolean;
  disabled?: boolean;
  size?: "small" | "medium" | "large";
  onClick?: () => void;
  className?: string;
}

export const HsIconButton = forwardRef<HTMLButtonElement, HsIconButtonProps>(
  function HsIconButton(
    {
      label,
      icon,
      variant = "subtle",
      selected,
      loading = false,
      disabled = false,
      size = "medium",
      onClick,
      className,
    },
    ref,
  ) {
    const appearance = selected ? "primary" : variant;
    return (
      <HsTooltip content={label}>
        <FluentButton
          ref={ref}
          appearance={appearance}
          className={mergeClasses(
            "hs-icon-button",
            `hs-icon-button--${variant}`,
            selected && "hs-icon-button--selected",
            className,
          )}
          icon={loading ? <Spinner size="tiny" /> : icon}
          disabled={disabled || loading}
          aria-busy={loading || undefined}
          aria-label={label}
          aria-pressed={selected}
          size={size}
          onClick={onClick}
        />
      </HsTooltip>
    );
  },
);

import type { ReactElement } from "react";
import {
  Menu as FluentMenu,
  MenuTrigger as FluentMenuTrigger,
  MenuPopover as FluentMenuPopover,
  MenuList as FluentMenuList,
  MenuItem as FluentMenuItem,
  MenuDivider as FluentMenuDivider,
  makeStyles,
  tokens,
} from "@fluentui/react-components";

/**
 * HsMenu — command/overflow menu over Fluent v9 Menu (§8 elevation tier).
 *
 * Declarative item list; each item carries its Japanese label. Dividers are
 * expressed with the literal item `{ key, divider: true }` — or interleave
 * real elements via `children` when the simple shape is not enough.
 */
const useMenuStyles = makeStyles({
  popover: {
    borderRadius: "var(--hs-radius-panel)",
    boxShadow: tokens.shadow8,
  },
});

export interface HsMenuItem {
  key: string;
  /** Japanese label (omit only for divider items). */
  label?: string;
  icon?: ReactElement;
  disabled?: boolean;
  /** Render a divider instead of an item. */
  divider?: boolean;
}

export interface HsMenuProps {
  /** Trigger element — wrapped in MenuTrigger (keep it a real button). */
  trigger: ReactElement;
  items: readonly HsMenuItem[];
  onSelect?: (key: string) => void;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Mount the popover into this node instead of document.body. */
  mountNode?: HTMLElement | null;
  /** Accessible name for the menu list. */
  ariaLabel?: string;
  positioning?: "below" | "above" | "before" | "after";
}

export function HsMenu({
  trigger,
  items,
  onSelect,
  open,
  onOpenChange,
  mountNode,
  ariaLabel,
  positioning = "below",
}: HsMenuProps) {
  const styles = useMenuStyles();
  return (
    <FluentMenu
      open={open}
      onOpenChange={(_, data) => onOpenChange?.(data.open)}
      mountNode={mountNode}
      positioning={positioning}
    >
      <FluentMenuTrigger disableButtonEnhancement>
        {trigger}
      </FluentMenuTrigger>
      <FluentMenuPopover className={styles.popover}>
        <FluentMenuList aria-label={ariaLabel}>
          {items.map((item) =>
            item.divider ? (
              <FluentMenuDivider key={item.key} />
            ) : (
              <FluentMenuItem
                key={item.key}
                icon={item.icon}
                disabled={item.disabled}
                onClick={() => onSelect?.(item.key)}
              >
                {item.label}
              </FluentMenuItem>
            ),
          )}
        </FluentMenuList>
      </FluentMenuPopover>
    </FluentMenu>
  );
}

import {
  Field,
  SpinButton,
  mergeClasses,
} from "@fluentui/react-components";

/**
 * HsNumericField — labelled numeric input (BPM, 小節番号, 秒数…).
 *
 * Built on Fluent SpinButton (keyboard ↑/↓ + stepper buttons) inside Field,
 * which wires label → control and renders the validation message. `error`
 * carries a Japanese message string and flips the field to the error state;
 * `hint` renders neutral helper text. Unit suffixes are shown via
 * SpinButton's displayValue without polluting the numeric value.
 */
export interface HsNumericFieldProps {
  /** Japanese field label — doubles as the input's accessible name. */
  label: string;
  value: number | null;
  min?: number;
  max?: number;
  step?: number;
  onChange?: (value: number | null) => void;
  /** Unit shown after the number, e.g. "BPM", "秒". */
  unit?: string;
  required?: boolean;
  disabled?: boolean;
  /** Japanese error message — sets the field's error state. */
  error?: string;
  /** Neutral helper text shown when there is no error. */
  hint?: string;
  className?: string;
}

export function HsNumericField({
  label,
  value,
  min,
  max,
  step,
  onChange,
  unit,
  required = false,
  disabled = false,
  error,
  hint,
  className,
}: HsNumericFieldProps) {
  const message = error ?? hint;
  return (
    <Field
      label={label}
      required={required}
      validationState={error ? "error" : "none"}
      validationMessage={message}
      className={mergeClasses("hs-field", className)}
    >
      <SpinButton
        value={value}
        displayValue={
          value == null ? undefined : `${value}${unit ? ` ${unit}` : ""}`
        }
        min={min}
        max={max}
        step={step}
        disabled={disabled}
        // Fluent's defaults ship English aria-labels; the copy contract
        // requires Japanese accessible names, derived from the field label.
        incrementButton={{ "aria-label": `${label}を増やす` }}
        decrementButton={{ "aria-label": `${label}を減らす` }}
        onChange={(_, data) => {
          if (data.value !== undefined) {
            onChange?.(data.value);
          } else if (data.displayValue !== undefined) {
            // Free-typed text: let the caller parse or reject it.
            const parsed = Number(data.displayValue.replace(/[^0-9.-]/g, ""));
            onChange?.(Number.isFinite(parsed) ? parsed : null);
          }
        }}
      />
    </Field>
  );
}

import { forwardRef, type ReactNode } from "react";
import { mergeClasses } from "@fluentui/react-components";
import { Dismiss16Regular } from "@fluentui/react-icons";
import { HsIconButton } from "./IconButton";
import { ja } from "../../strings/ja";

/**
 * HsPanel — section container (プロパティ, 書き出しオプション, 設定群…).
 *
 * Persistent workspace surfaces stay flat (§8): separation is by border +
 * surface contrast. `elevated` is for floating panels only and switches to
 * --hs-surface-elevated + --hs-elevation-popover.
 */
export interface HsPanelProps {
  /** Japanese section title — shown in the panel header. */
  title?: string;
  /** Heading level for the title (default 3); pick to keep the outline. */
  titleLevel?: 2 | 3 | 4;
  /** Header actions (icon buttons etc.) rendered before the close button. */
  actions?: ReactNode;
  /** When set, renders a close button; label defaults to 閉じる. */
  onClose?: () => void;
  closeLabel?: string;
  /** Floating presentation (elevated surface + shadow). */
  elevated?: boolean;
  /** Accessible name; defaults to the title when present. */
  ariaLabel?: string;
  /** Remove the default body padding for flush content (lists, rulers). */
  flush?: boolean;
  className?: string;
  children: ReactNode;
}

export const HsPanel = forwardRef<HTMLElement, HsPanelProps>(
  function HsPanel(
    {
      title,
      titleLevel = 3,
      actions,
      onClose,
      closeLabel,
      elevated = false,
      ariaLabel,
      flush = false,
      className,
      children,
    },
    ref,
  ) {
    const hasHeader = title != null || actions != null || onClose != null;
    const TitleTag = `h${titleLevel}` as const;
    return (
      <section
        ref={ref}
        className={mergeClasses(
          "hs-panel",
          elevated && "hs-panel--elevated",
          className,
        )}
        aria-label={ariaLabel ?? title}
      >
        {hasHeader ? (
          <header className="hs-panel__header">
            {title ? (
              <TitleTag className="hs-panel__title">{title}</TitleTag>
            ) : null}
            <span className="hs-panel__header-spacer" />
            {actions}
            {onClose ? (
              <HsIconButton
                label={closeLabel ?? ja.common.close}
                icon={<Dismiss16Regular />}
                size="small"
                onClick={onClose}
              />
            ) : null}
          </header>
        ) : null}
        <div
          className={mergeClasses(
            "hs-panel__body",
            flush && "hs-panel__body--flush",
          )}
        >
          {children}
        </div>
      </section>
    );
  },
);

import type { ReactElement, ReactNode } from "react";
import {
  Popover as FluentPopover,
  PopoverTrigger as FluentPopoverTrigger,
  PopoverSurface as FluentPopoverSurface,
  makeStyles,
  tokens,
} from "@fluentui/react-components";

/**
 * HsPopover — anchored floating surface (DESIGN_SYSTEM §8 elevation tier).
 *
 * Surface chrome follows the Fluent theme tokens (context-correct inside
 * portals and in the gallery's dual-theme sections); HornScribe geometry is
 * applied through the --hs-radius-panel semantic token.
 *
 * `inline` renders the surface in-flow instead of a portal — used by the
 * dev gallery so fixtures live inside their light/dark theme section.
 */
const usePopoverStyles = makeStyles({
  surface: {
    borderRadius: "var(--hs-radius-panel)",
    boxShadow: tokens.shadow16,
    transitionDuration: "var(--hs-motion-panel)",
    transitionTimingFunction: "var(--hs-ease-decelerate)",
  },
});

export interface HsPopoverProps {
  /** The element the popover anchors to (wrapped in PopoverTrigger). */
  trigger: ReactElement;
  children: ReactNode;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Render in-flow (no portal) — dev gallery fixtures. */
  inline?: boolean;
