      <div className="hs-slider">
        <FluentSlider
          value={value}
          min={min}
          max={max}
          step={step}
          disabled={disabled}
          onChange={(_, data) => onChange?.(data.value)}
        />
        {showValue ? (
          <span className="hs-slider__value">{display}</span>
        ) : null}
      </div>
    </Field>
  );
