export default function Gallery({
  themeMode,
  onThemeMode,
}: {
  themeMode: ThemeMode;
  onThemeMode: (mode: ThemeMode) => void;
}) {
  const themes: readonly { id: ResolvedTheme; label: string }[] = [
    { id: "light", label: ja.gallery.themeLight },
    { id: "dark", label: ja.gallery.themeDark },
  ];

  // Open fixtures (menu popover) call scrollIntoView when Fluent autofocuses
  // the first item on mount; pin the gallery scroll to the top so the page
  // always opens at the light-theme section. The rAF covers any deferred
  // scroll scheduled after this effect runs.
  useEffect(() => {
    const pin = () => {
      const root = document.querySelector<HTMLElement>(".hs-gallery");
      if (root) root.scrollTop = 0;
      document.documentElement.scrollTop = 0;
      document.body.scrollTop = 0;
    };
    pin();
    const raf = requestAnimationFrame(pin);
    return () => cancelAnimationFrame(raf);
  }, []);

  return (
    <div className="hs-gallery" role="main" aria-label={ja.gallery.title}>
      <header className="hs-gallery__header">
        <h1 className="hs-gallery__title">{ja.gallery.title}</h1>
        <StatusBadge tone="info" label={ja.gallery.devBadge} />
        <span className="hs-gallery__spacer" />
        <SegmentedControl
          options={THEME_OPTIONS}
          value={themeMode}
          onChange={onThemeMode}
          ariaLabel={ja.settings.themeLabel}
        />
        <HsButton
          variant="subtle"
          onClick={() => {
            window.location.hash = "";
          }}
        >
          {ja.common.back}
        </HsButton>
        <p className="hs-gallery__note">{ja.gallery.note}</p>
      </header>

      {themes.map((t) => (
        <section key={t.id} data-hs-theme={t.id} className="hs-gallery__theme">
          <FluentProvider
            theme={t.id === "dark" ? hsDarkTheme : hsLightTheme}
            style={{ display: "contents" }}
          >
            <h2 className="hs-gallery__theme-title">{t.label}</h2>
            <PrimitiveSections />
          </FluentProvider>
        </section>
      ))}
    </div>
  );
}

/**
 * Dev gallery (#/dev/gallery) — layout + simulated-state fixture styling.
 *
 * Simulated pseudo-states (.hs-sim-*) exist so screenshot-based visual
 * regression can capture hover/pressed/focus without driving a mouse.
 * They paint the same --hs-* tokens the real :hover/:active/:focus-visible
 * rules use; they are dev-page plumbing, not product styling.
 */

/* Fixed overlay: the dev route replaces the shell entirely, so the gallery
   owns the viewport and is its own scroll container (the FluentProvider
   wrapper has no constrained height, and body is overflow:hidden). */
.hs-gallery {
  position: fixed;
  inset: 0;
  overflow: auto;
  background: var(--hs-surface-app);
  color: var(--hs-text-primary);
}

/* ---- Header ---- */
.hs-gallery__header {
  position: sticky;
  top: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--hs-space-sm);
  padding: var(--hs-space-sm) var(--hs-space-md);
  background: var(--hs-surface-panel);
  border-bottom: 1px solid var(--hs-border-subtle);
}
.hs-gallery__title {
  margin: 0;
  font-size: var(--hs-font-size-title);
  line-height: var(--hs-line-height-title);
  font-weight: var(--hs-font-weight-title);
}
.hs-gallery__note {
  flex-basis: 100%;
  margin: 0;
  font-size: var(--hs-font-size-caption);
  line-height: var(--hs-line-height-caption);
  color: var(--hs-text-muted);
}
.hs-gallery__spacer {
  flex: 1 1 auto;
}

/* ---- Per-theme sections: data-hs-theme rebinds every --hs-* token ---- */
.hs-gallery__theme {
  padding: var(--hs-space-md) var(--hs-space-md) var(--hs-space-xl);
  background: var(--hs-surface-app);
  color: var(--hs-text-primary);
}
.hs-gallery__theme + .hs-gallery__theme {
  border-top: 2px solid var(--hs-border-strong);
}
.hs-gallery__theme-title {
  margin: 0 0 var(--hs-space-md);
  font-size: var(--hs-font-size-subtitle);
  line-height: var(--hs-line-height-subtitle);
  font-weight: var(--hs-font-weight-title);
  color: var(--hs-text-secondary);
}

.hs-gallery__section {
  margin: 0 0 var(--hs-space-xl);
}
.hs-gallery__section-title {
  margin: 0 0 var(--hs-space-sm);
  font-size: var(--hs-font-size-body);
  line-height: var(--hs-line-height-body);
  font-weight: var(--hs-font-weight-emphasis);
}

/* ---- Fixture grid ---- */
.hs-fixture-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--hs-space-ms);
  align-items: start;
}
.hs-fixture-grid--wide {
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
}

.hs-fixture {
  margin: 0;
  min-width: 0;
}
.hs-fixture__stage {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--hs-space-sm);
  min-height: 56px;
  padding: var(--hs-space-sm);
  background: var(--hs-surface-elevated);
  border: 1px solid var(--hs-border-subtle);
  border-radius: var(--hs-radius-panel);
  /* Stretch form controls inside the cell. */
  text-align: center;
}
.hs-fixture__stage .fui-Field {
  width: 100%;
  text-align: start;
}
.hs-fixture__stage--stretch {
  align-items: stretch;
}
.hs-fixture__caption {
  margin-top: var(--hs-space-xs);
  font-size: var(--hs-font-size-caption);
  line-height: var(--hs-line-height-caption);
  color: var(--hs-text-muted);
  text-align: center;
}

/* Contained overlay stage: mountNode target for tooltip / popover / menu /
   sheet fixtures. transform makes position:fixed descendants (drawer)
   resolve against the stage box instead of the viewport. */
.hs-overlay-stage {
  position: relative;
  transform: translateZ(0);
  overflow: hidden;
  min-height: 220px;
  align-items: flex-start;
  justify-content: flex-start;
}
.hs-overlay-stage--tall {
  min-height: 300px;
}
.hs-overlay-stage .fui-Drawer,
.hs-overlay-stage .fui-OverlayDrawer {
  position: absolute;
}

/* ===================== Simulated pseudo-states =====================
   Only inside fixture stages. Tokens mirror the real interaction colors:
   - accent fill variants use --hs-accent-hover / --hs-accent-pressed
   - danger fill variants use --hs-danger-hover / --hs-danger-pressed
   - neutral variants use --hs-control-hover / --hs-control-pressed
   - focus uses the §16 ring contract (2px --hs-focus + offset)          */

.hs-sim-hover .hs-button--primary:not(:disabled),
.hs-sim-hover .hs-icon-button--primary:not(:disabled) {
  background-color: var(--hs-accent-hover);
}
.hs-sim-pressed .hs-button--primary:not(:disabled),
.hs-sim-pressed .hs-icon-button--primary:not(:disabled) {
  background-color: var(--hs-accent-pressed);
}
.hs-sim-hover .hs-button--secondary:not(:disabled),
.hs-sim-hover .hs-button--subtle:not(:disabled),
.hs-sim-hover .hs-icon-button:not(:disabled) {
  background-color: var(--hs-control-hover);
}
.hs-sim-pressed .hs-button--secondary:not(:disabled),
.hs-sim-pressed .hs-button--subtle:not(:disabled),
.hs-sim-pressed .hs-icon-button:not(:disabled) {
  background-color: var(--hs-control-pressed);
}
.hs-sim-hover .hs-button--danger:not(:disabled) {
  background-color: var(--hs-danger-hover);
}
.hs-sim-pressed .hs-button--danger:not(:disabled) {
  background-color: var(--hs-danger-pressed);
}

/* Segmented control: unselected item picks up the hover wash. */
.hs-sim-hover .hs-segmented__item:not(:disabled):not([aria-checked="true"]) {
  background: var(--hs-control-hover);
}
.hs-sim-pressed .hs-segmented__item:not(:disabled):not([aria-checked="true"]) {
  background: var(--hs-control-pressed);
}

/* Field controls: hover strengthens the input border (≥3:1 boundary). */
.hs-sim-hover .fui-Input,
.hs-sim-hover .fui-Select,
.hs-sim-hover .fui-SpinButton {
  border-color: var(--hs-border-strong);
}
.hs-sim-hover .fui-Slider__thumb {
  box-shadow: 0 0 0 4px var(--hs-control-hover);
}

/* Focus simulation = the real HornScribe focus ring contract. */
.hs-sim-focus :where(button, input, select, [role="radio"], .fui-Slider__thumb, .hs-segmented__item) {
  outline: var(--hs-focus-width) solid var(--hs-focus) !important;
  outline-offset: var(--hs-focus-offset);
}

/* ---- Screen-state fixture cards ---- */
.hs-fixture-card {
  display: flex;
  flex-direction: column;
  gap: var(--hs-space-sm);
}
.hs-fixture-card__title {
  margin: 0;
  font-size: var(--hs-font-size-body);
  line-height: var(--hs-line-height-body);
  font-weight: var(--hs-font-weight-emphasis);
}
.hs-fixture-card__text {
  margin: 0;
  font-size: var(--hs-font-size-compact);
  line-height: var(--hs-line-height-compact);
  color: var(--hs-text-secondary);
}
.hs-fixture-card__actions {
  display: flex;
  gap: var(--hs-space-sm);
  flex-wrap: wrap;
  margin-top: var(--hs-space-xs);
}

/* Transcribing stage list (GUI_UX_SPEC §5 shape: ✓ done ● active ○ pending) */
.hs-stage-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: var(--hs-space-xs);
}
.hs-stage {
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  font-size: var(--hs-font-size-compact);
  line-height: var(--hs-line-height-compact);
  color: var(--hs-text-secondary);
}
.hs-stage--done {
  color: var(--hs-status-success);
}
.hs-stage--active {
  color: var(--hs-status-info);
  font-weight: var(--hs-font-weight-emphasis);
}
.hs-stage__icon {
  display: inline-flex;
  width: 16px;
  justify-content: center;
}

/**
 * HornScribe app shell layout + token consumers.
 * Colors come only from --hs-* semantic tokens (tokens.css).
 */

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--hs-font-family);
  font-size: var(--hs-font-size-body);
  color: var(--hs-text-primary);
  background: var(--hs-surface-app);
  overflow: hidden;
}

/* ---- Visible keyboard focus (DESIGN_SYSTEM §16) ----
   2px+, distinct from adjacent surface; Fluent v9 components draw their own
   compatible focus ring, this guarantees the same contract for every other
   focusable region (waveform, score surface, segmented control, links). */
:focus-visible {
  outline: 2px solid var(--hs-focus);
  outline-offset: 2px;
  border-radius: var(--hs-radius-input);
}
/* Never remove the outline without a replacement. */
:focus:not(:focus-visible) {
  outline: none;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* ============================ App shell ============================ */
/* GUI_UX_SPEC §2 information architecture:
   title bar → command bar → waveform → score workspace → transport → status */
.hs-shell {
  display: grid;
  grid-template-rows: auto auto auto minmax(0, 1fr) auto auto;
  grid-template-areas:
    "titlebar"
    "commandbar"
    "waveform"
    "main"
    "transport"
    "statusbar";
  height: 100%;
  min-width: 0;
  background: var(--hs-surface-app);
  color: var(--hs-text-primary);
}

/* ---- Title bar area (in-app; native window chrome is kept) ---- */
.hs-titlebar {
  grid-area: titlebar;
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  height: 32px;
  padding: 0 var(--hs-space-ms);
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-secondary);
  background: var(--hs-surface-panel);
  border-bottom: 1px solid var(--hs-border-subtle);
  user-select: none;
}
.hs-titlebar__app {
  font-weight: 600;
  color: var(--hs-text-primary);
}
.hs-titlebar__doc {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---- Command bar (DESIGN_SYSTEM §10: ~44px, never scrolls) ---- */
.hs-commandbar {
  grid-area: commandbar;
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  height: 44px;
  padding: 0 var(--hs-space-ms);
  background: var(--hs-surface-panel);
  border-bottom: 1px solid var(--hs-border-subtle);
  overflow: hidden;
  white-space: nowrap;
}
.hs-commandbar__spacer {
  flex: 1 1 auto;
  min-width: var(--hs-space-sm);
}

/* ---- Segmented control (DESIGN_SYSTEM §11: text labels, never icon-only) ---- */
.hs-segmented {
  display: inline-flex;
  flex: 0 0 auto;
  border: 1px solid var(--hs-border-strong);
  border-radius: var(--hs-radius-input);
  overflow: hidden;
  background: var(--hs-surface-elevated);
}
.hs-segmented__item {
  appearance: none;
  border: none;
  background: transparent;
  color: var(--hs-text-secondary);
  font-family: var(--hs-font-family);
  font-size: var(--hs-font-size-compact);
  line-height: 1;
  padding: 8px 12px;
  cursor: pointer;
  white-space: nowrap;
}
.hs-segmented__item + .hs-segmented__item {
  border-left: 1px solid var(--hs-border-subtle);
}
.hs-segmented__item:hover {
  background: var(--hs-control-hover);
}
/* selected state = fill + weight + border cues combined (§11);
   on-accent text color keeps ≥4.5:1 in both themes (dark accent is light,
   so the foreground flips to dark ink via --hs-accent-foreground). */
.hs-segmented__item[aria-checked="true"] {
  background: var(--hs-accent);
  color: var(--hs-accent-foreground);
  font-weight: var(--hs-font-weight-emphasis);
  box-shadow: inset 0 0 0 1px var(--hs-accent-pressed);
}
.hs-segmented__item:focus-visible {
  outline-offset: -2px;
}

/* ---- Waveform region (GUI_UX_SPEC §8: 96–120px standard) ---- */
.hs-waveform {
  grid-area: waveform;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 96px;
  min-height: 64px;
  max-height: 35vh;
  background: var(--hs-surface-panel);
  border-bottom: 1px solid var(--hs-border-subtle);
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-compact);
}

/* ---- Score workspace + properties ---- */
.hs-main {
  grid-area: main;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  min-height: 0;
  min-width: 0;
}

.hs-score {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--hs-space-md);
  min-width: 0;
  min-height: 0;
  padding: var(--hs-space-lg);
  background: var(--hs-surface-score);
  color: var(--hs-text-primary);
  /* Score paper keeps a hairline radius, not decorative rounding (§7). */
  border-radius: var(--hs-radius-score-paper);
  overflow: auto;
}

.hs-properties {
  width: 264px;
  min-width: 200px;
  max-width: 320px;
  padding: var(--hs-space-md);
  background: var(--hs-surface-panel);
  border-left: 1px solid var(--hs-border-subtle);
  color: var(--hs-text-secondary);
  overflow: auto;
}
.hs-properties__title {
  margin: 0 0 var(--hs-space-sm);
  font-size: var(--hs-font-size-subtitle);
  font-weight: 600;
  color: var(--hs-text-primary);
}
.hs-properties__body {
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-muted);
}

/* §21 responsive: below 1200px the panel collapses to a drawer candidate. */
@media (max-width: 1199px) {
  .hs-properties {
    display: none;
  }
}

/* ---- Empty state (GUI_UX_SPEC §3, §19: compact, clear CTA) ---- */
.hs-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--hs-space-sm);
  text-align: center;
  max-width: 46em;
}
.hs-empty__title {
  margin: 0;
  font-size: var(--hs-font-size-display);
  font-weight: 400;
}
.hs-empty__or {
  margin: 0;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-caption);
}
.hs-empty__formats {
  margin: var(--hs-space-xs) 0 0;
  color: var(--hs-text-secondary);
  font-size: var(--hs-font-size-compact);
}
.hs-empty__privacy {
  margin: 0;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-caption);
}

/* ---- Transport (GUI_UX_SPEC §9) ---- */
.hs-transport {
  grid-area: transport;
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  height: 52px;
  padding: 0 var(--hs-space-ms);
  background: var(--hs-surface-panel);
  border-top: 1px solid var(--hs-border-subtle);
}
.hs-transport__time {
  font-variant-numeric: tabular-nums; /* §5: timecode uses tabular numerals */
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-secondary);
  margin-left: var(--hs-space-sm);
  white-space: nowrap;
}
.hs-transport__spacer {
  flex: 1 1 auto;
}

/* ---- Status bar ---- */
.hs-statusbar {
  grid-area: statusbar;
  display: flex;
  align-items: center;
  gap: var(--hs-space-md);
  height: 26px;
  padding: 0 var(--hs-space-ms);
  font-size: var(--hs-font-size-caption);
  color: var(--hs-text-muted);
  background: var(--hs-surface-panel);
  border-top: 1px solid var(--hs-border-subtle);
  user-select: none;
}
.hs-statusbar__message {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hs-statusbar__spacer {
  flex: 1 1 auto;
}

/* ====================== Primitives (components/primitives) ======================
   Only --hs-* semantic tokens; raw values live exclusively in tokens.css. */

/* ---- HsButton (§9): danger re-tints the primary fill to palette red ----
   Double-class selectors keep precedence over Fluent's atomic classes. */
.hs-button.hs-button--danger:not(:disabled) {
  background-color: var(--hs-danger);
  color: var(--hs-danger-foreground);
  border-color: transparent;
}
.hs-button.hs-button--danger:not(:disabled):hover {
  background-color: var(--hs-danger-hover);
}
.hs-button.hs-button--danger:not(:disabled):active {
  background-color: var(--hs-danger-pressed);
}
/* State changes use the fast motion tier (§18). */
.hs-button {
  transition-duration: var(--hs-motion-fast);
  transition-timing-function: var(--hs-ease-standard);
}

/* ---- Segmented control additions (§11, §17) ---- */
.hs-segmented__item:disabled {
  color: var(--hs-text-disabled);
  cursor: not-allowed;
}
.hs-segmented__item:disabled:hover {
  background: transparent;
}
.hs-segmented__item {
  transition: background-color var(--hs-motion-fast) var(--hs-ease-standard);
}

/* ---- StatusBadge / ReviewBadge (§15): tint + glyph + (review) dotted cue ---- */
.hs-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--hs-space-xs);
  padding: 1px var(--hs-space-sm);
  border-radius: var(--hs-radius-input);
  border: 1px solid transparent;
  font-size: var(--hs-font-size-caption);
  line-height: var(--hs-line-height-caption);
  font-weight: var(--hs-font-weight-emphasis);
  white-space: nowrap;
  user-select: none;
}
.hs-badge__icon {
  display: inline-flex;
  font-size: 14px;
}
.hs-badge--neutral {
  color: var(--hs-text-secondary);
  background: var(--hs-status-neutral-subtle);
  border-color: color-mix(in srgb, currentColor 25%, transparent);
}
.hs-badge--info {
  color: var(--hs-status-info);
  background: var(--hs-status-info-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
.hs-badge--success {
  color: var(--hs-status-success);
  background: var(--hs-status-success-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
.hs-badge--warning {
  color: var(--hs-status-warning);
  background: var(--hs-status-warning-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
.hs-badge--error {
  color: var(--hs-status-error);
  background: var(--hs-status-error-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
/* §15: the 要確認 marker adds a dotted underline — review is never red. */
.hs-badge--needs-review .hs-badge__label {
  border-bottom: 2px dotted var(--hs-review-marker);
}

/* ---- HsPanel (§8): flat separation by border; elevated for floats ---- */
.hs-panel {
  display: flex;
  flex-direction: column;
  min-width: 0;
  background: var(--hs-surface-panel);
  border: 1px solid var(--hs-border-subtle);
  border-radius: var(--hs-radius-panel);
  color: var(--hs-text-primary);
}
.hs-panel--elevated {
  background: var(--hs-surface-elevated);
  box-shadow: var(--hs-elevation-popover);
}
.hs-panel__header {
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  padding: var(--hs-space-sm) var(--hs-space-ms);
  border-bottom: 1px solid var(--hs-border-subtle);
  min-height: 40px;
}
.hs-panel__title {
  margin: 0;
  font-size: var(--hs-font-size-subtitle);
  line-height: var(--hs-line-height-subtitle);
  font-weight: var(--hs-font-weight-title);
}
.hs-panel__header-spacer {
  flex: 1 1 auto;
}
.hs-panel__body {
  padding: var(--hs-space-md);
  min-width: 0;
}
.hs-panel__body--flush {
  padding: 0;
}

/* ---- HsSlider: track + tabular readout (§5) ---- */
.hs-slider {
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
}
.hs-slider .fui-Slider {
  flex: 1 1 auto;
}
.hs-slider__value {
  flex: 0 0 auto;
  min-width: 3.5em;
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-size: var(--hs-font-size-compact);
  line-height: var(--hs-line-height-compact);
  color: var(--hs-text-secondary);
}

/* ---- Settings (auxiliary screen, §18): replaces the workspace rows ---- */
.hs-settings-wrap {
  grid-row: commandbar / transport; /* spans commandbar…main rows */
  display: flex;
  min-height: 0;
  min-width: 0;
}
.hs-settings {
  flex: 1 1 auto;
  min-height: 0;
  min-width: 0;
  padding: var(--hs-space-lg);
  background: var(--hs-surface-app);
  overflow: auto;
}
.hs-settings__title {
  margin: 0 0 var(--hs-space-md);
  font-size: var(--hs-font-size-title);
  font-weight: 600;
}
/* Section chrome (border / radius / padding) comes from the HsPanel
   primitive; this class only constrains width and rhythm. */
.hs-settings__section {
  margin: 0 0 var(--hs-space-lg);
  max-width: 560px;
}
.hs-settings__note {
  margin: 0;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-compact);
}

import {
  createLightTheme,
  createDarkTheme,
  type BrandVariants,
  type Theme,
} from "@fluentui/react-components";

/**
 * Fluent v9 theme mapping for HornScribe (docs/DESIGN_SYSTEM.md §3).
 *
 * The brand ramp is Fluent's blue ramp: the accent deliberately tracks the
 * Windows/Fluent system feel rather than a fixed custom brand color.
 * HornScribe-specific semantics live in the --hs-* CSS tokens (tokens.css);
 * the Fluent theme below governs v9 component internals.
 */
const hornscribeBrand: BrandVariants = {
  10: "#061724",
  20: "#082338",
  30: "#0a2e4a",
  40: "#0c3b5e",
  50: "#0e4775",
  60: "#0f548c",
  70: "#115ea3",
  80: "#0f6cbd",
  90: "#2886de",
  100: "#479ef5",
  110: "#62abf5",
  120: "#77b7f7",
  130: "#96c6fa",
  140: "#b4d6fa",
  150: "#cfe4fa",
  160: "#ebf3fc",
};

/**
 * §5 typography: the same stack as --hs-font-family so Fluent component
 * internals render Japanese text through Yu Gothic UI / Meiryo too.
 */
const hsFontStack =
  '"Segoe UI Variable","Segoe UI","Yu Gothic UI","Meiryo",sans-serif';

export const hsLightTheme: Theme = {
  ...createLightTheme(hornscribeBrand),
  fontFamilyBase: hsFontStack,
  fontFamilyNumeric: hsFontStack,
};

export const hsDarkTheme: Theme = {
  ...createDarkTheme(hornscribeBrand),
  fontFamilyBase: hsFontStack,
  fontFamilyNumeric: hsFontStack,
};

export type ThemeMode = "system" | "light" | "dark";
export type ResolvedTheme = "light" | "dark";

/**
 * HornScribe semantic design tokens (docs/DESIGN_SYSTEM.md §3).
 *
 * Token layers: primitive → semantic (--hs-*) → component.
 * Components must reference --hs-* tokens, never raw hex values.
 * The raw values in THIS file are the documented §25 exception
 * (the single place where primitives are bound to semantics).
 *
 * Values are Fluent v9 neutral/brand palette aligned: the accent stays
 * consistent with Windows/Fluent instead of a fixed brand color (§3).
 */

:root {
  /* ---- Typography (DESIGN_SYSTEM §5) ----
     Japanese-capable stack: Yu Gothic UI / Meiryo before generic fallback. */
  --hs-font-family:
    "Segoe UI Variable",
    "Segoe UI",
    "Yu Gothic UI",
    "Meiryo",
    sans-serif;
  --hs-font-size-caption: 12px;
  --hs-font-size-compact: 13px;
  --hs-font-size-body: 14px;
  --hs-font-size-subtitle: 16px;
  --hs-font-size-title: 20px;
  --hs-font-size-display: 24px;
  /* body-emphasis is a weight variant of body (§5). */
  --hs-font-weight-regular: 400;
  --hs-font-weight-emphasis: 600;
  --hs-font-weight-title: 600;
  /* Line heights keep 4px-grid alignment (§6). */
  --hs-line-height-caption: 16px;
  --hs-line-height-compact: 18px;
  --hs-line-height-body: 20px;
  --hs-line-height-subtitle: 22px;
  --hs-line-height-title: 28px;
  --hs-line-height-display: 32px;

  /* ---- Spacing, 4px grid (§6) ---- */
  --hs-space-micro: 2px;
  --hs-space-xs: 4px;
  --hs-space-sm: 8px;
  --hs-space-ms: 12px;
  --hs-space-md: 16px;
  --hs-space-ml: 20px;
  --hs-space-lg: 24px;
  --hs-space-xl: 32px;
  --hs-space-2xl: 48px;

  /* ---- Geometry (§7): radius is functional, not decorative ---- */
  --hs-radius-input: 6px;
  --hs-radius-panel: 8px;
  --hs-radius-modal: 10px;
  --hs-radius-score-paper: 3px;

  /* ---- Motion (§18): durations + easing curves ---- */
  --hs-motion-fast: 100ms;
  --hs-motion-normal: 180ms;
  --hs-motion-panel: 220ms;
  --hs-motion-dialog: 240ms;
  /* Fluent-curve aligned: standard for color/position, decelerate for
     entrances, accelerate for exits. */
  --hs-ease-standard: cubic-bezier(0.8, 0, 0.2, 1);
  --hs-ease-decelerate: cubic-bezier(0.1, 0.9, 0.2, 1);
  --hs-ease-accelerate: cubic-bezier(0.9, 0.1, 1, 0.2);

  /* ---- Focus geometry (§16): 2px+, offset from control bounds ---- */
  --hs-focus-width: 2px;
  --hs-focus-offset: 2px;
}

/* Reduced motion (§18): panel/dialog transitions collapse to near-instant
   and crossfades shorten; JS-driven animation code should read these tokens
   instead of hard-coded ms values. */
@media (prefers-reduced-motion: reduce) {
  :root {
    --hs-motion-fast: 1ms;
    --hs-motion-normal: 1ms;
    --hs-motion-panel: 1ms;
    --hs-motion-dialog: 1ms;
  }
}

/* ============================= LIGHT ============================= */
:root,
[data-hs-theme="light"] {
  --hs-surface-app: #f3f3f3;
  --hs-surface-score: #ffffff;
  --hs-surface-panel: #fafafa;
  --hs-surface-elevated: #ffffff;

  --hs-text-primary: #242424;
  --hs-text-secondary: #424242;
  --hs-text-muted: #616161;
  --hs-text-disabled: #bdbdbd;

  --hs-border-subtle: #e0e0e0;
  --hs-border-strong: #757575;

  --hs-accent: #0f6cbd;
  --hs-accent-hover: #115ea3;
  --hs-accent-pressed: #0f548c;
  /* Text/icons placed on --hs-accent fills (selected segments, primary). */
  --hs-accent-foreground: #ffffff;
  /* Quiet accent tint for selected/informational washes. */
  --hs-accent-subtle: #ebf3fc;

  /* Neutral interaction tints for subtle/secondary control states. */
  --hs-control-hover: rgba(0, 0, 0, 0.06);
  --hs-control-pressed: rgba(0, 0, 0, 0.1);

  --hs-focus: #000000;

  --hs-status-info: #0f6cbd;
  --hs-status-warning: #986f0b;
  --hs-status-error: #c50f1f;
  --hs-status-success: #107c10;
  /* Tinted surfaces behind status text/badges (≥4.5:1 with the matching
     --hs-status-* text color; checked against these paired values only). */
  --hs-status-info-subtle: #ebf3fc;
  --hs-status-warning-subtle: #fff4ce;
  --hs-status-error-subtle: #fde7e9;
  --hs-status-success-subtle: #f1faf1;
  --hs-status-neutral-subtle: #f0f0f0;

  /* Destructive-action fill (§9 danger button, §20): palette red family,
     same values in dark theme — distinct from --hs-status-error which is
     the text/icon signal color. */
  --hs-danger: #c50f1f;
  --hs-danger-hover: #b10e1c;
  --hs-danger-pressed: #960b18;
  --hs-danger-foreground: #ffffff;

  /* §15: 要確認 cue = warning tint, never error red. */
  --hs-review-tint: #fff4ce;

  --hs-waveform: #5f6b73;
  --hs-waveform-played: rgba(15, 108, 189, 0.75);
  --hs-waveform-selection: rgba(15, 108, 189, 0.22);
  --hs-playhead: #0c3b5e;

  /* Score paper (§13 option A): paper stays light in both themes, so the
     ink/staff tokens keep their light-paper values in the dark block too. */
  --hs-score-ink: #1a1a1a;
  --hs-score-staff: #333333;
  --hs-score-paper-border: #d4d4d4;
  --hs-score-selection: rgba(15, 108, 189, 0.25);
  --hs-score-active-note: #0f6cbd;
  --hs-score-current-measure: rgba(0, 0, 0, 0.05);
  --hs-review-marker: #986f0b;

  /* ---- Elevation (§8): reserved for menu/popover/sheet/drag; the
     persistent workspace itself stays flat and separates by border. ---- */
  --hs-elevation-menu:
    0 4px 8px rgba(0, 0, 0, 0.14),
    0 0 2px rgba(0, 0, 0, 0.12);
  --hs-elevation-popover:
    0 8px 16px rgba(0, 0, 0, 0.14),
    0 0 2px rgba(0, 0, 0, 0.12);
  --hs-elevation-sheet:
    0 16px 32px rgba(0, 0, 0, 0.2),
    0 0 4px rgba(0, 0, 0, 0.12);
  --hs-elevation-drag:
    0 8px 16px rgba(0, 0, 0, 0.2),
    0 0 2px rgba(0, 0, 0, 0.12);
}

/* ============================= DARK ============================== */
/* DESIGN_SYSTEM §13 option A: dark chrome + light score paper.      */
/* --hs-surface-score and the score-ink tokens intentionally stay     */
/* light so notation keeps normal readability on a dark shell.        */
[data-hs-theme="dark"] {
  --hs-surface-app: #1f1f1f;
  --hs-surface-score: #fafafa;
  --hs-surface-panel: #292929;
  --hs-surface-elevated: #383838;

  --hs-text-primary: #ffffff;
  --hs-text-secondary: #d6d6d6;
  --hs-text-muted: #adadad;
  --hs-text-disabled: #5c5c5c;

  --hs-border-subtle: #404040;
  --hs-border-strong: #adadad;

  --hs-accent: #479ef5;
  --hs-accent-hover: #62abf5;
  --hs-accent-pressed: #2886de;
  /* The dark accent is light, so on-accent text flips to dark ink. */
  --hs-accent-foreground: #1a1a1a;
  --hs-accent-subtle: #0a2e4a;

  --hs-control-hover: rgba(255, 255, 255, 0.08);
  --hs-control-pressed: rgba(255, 255, 255, 0.12);

  --hs-focus: #ffffff;

  --hs-status-info: #62abf5;
  --hs-status-warning: #fee06e;
  --hs-status-error: #f1707b;
  --hs-status-success: #9fd89f;
  --hs-status-info-subtle: #0a2e4a;
  --hs-status-warning-subtle: #443a08;
  --hs-status-error-subtle: #3f1011;
  --hs-status-success-subtle: #052501;
  --hs-status-neutral-subtle: #3a3a3a;

  /* Danger fill is the palette red family in both themes. */
  --hs-danger: #c50f1f;
  --hs-danger-hover: #b10e1c;
  --hs-danger-pressed: #960b18;
  --hs-danger-foreground: #ffffff;

  --hs-review-tint: #443a08;

  --hs-waveform: #9eaab2;
  --hs-waveform-played: rgba(71, 158, 245, 0.8);
  --hs-waveform-selection: rgba(71, 158, 245, 0.3);
  --hs-playhead: #a6c8fa;

  /* Score marks land on the (light) score paper in both themes. */
  --hs-score-ink: #1a1a1a;
  --hs-score-staff: #333333;
  --hs-score-paper-border: #c9c9c9;
  --hs-score-selection: rgba(15, 108, 189, 0.25);
  --hs-score-active-note: #0f6cbd;
  --hs-score-current-measure: rgba(0, 0, 0, 0.06);
  --hs-review-marker: #8a6308;

  --hs-elevation-menu:
    0 4px 8px rgba(0, 0, 0, 0.4),
    0 0 2px rgba(0, 0, 0, 0.3);
  --hs-elevation-popover:
    0 8px 16px rgba(0, 0, 0, 0.45),
    0 0 2px rgba(0, 0, 0, 0.3);
  --hs-elevation-sheet:
    0 16px 32px rgba(0, 0, 0, 0.55),
    0 0 4px rgba(0, 0, 0, 0.35);
  --hs-elevation-drag:
    0 8px 16px rgba(0, 0, 0, 0.5),
    0 0 2px rgba(0, 0, 0, 0.3);
}
